     * 통검 한정, 오피스에서는 그대로 0원을 넣어준다.
     */
    public void updateMemberPrice() {
        if (memberPrice == null || memberPrice == 0) {
            this.memberPrice = lowestPrice;
            this.memberTotalPrice = this.totalPrice;
        }

        if (memberPrice < lowestPrice) {
            this.memberPriceLowerYN = "Y";
        } else if (memberPrice > lowestPrice) {
            this.memberPriceLowerYN = "N";
        }

        if (unitMemberPrice == null || unitMemberPrice == 0) {
            this.unitMemberPrice = unitLowPrice;
            this.unitMemberTotalPrice = this.unitTotalPrice;
        }
    }

